PDBe's accession list includes cross-mapped entries (e.g., 1M17 = SRC), so I need chain-level SIFTS validation. Let me query RCSB for polymer entities aligned to P00533 with their chain IDs.

<execute>
#!BASH
cat > /workspace/step2_entities.py <<'PYEOF'
import json, requests, time

URL = "https://search.rcsb.org/rcsbsearch/v2/query"
query = {
    "query": {
        "type": "terminal", "service": "text",
        "parameters": {
            "attribute": "rcsb_polymer_entity_container_identifiers.reference_sequence_identifiers.database_accession",
            "operator": "exact_match", "value": "P00533",
        },
    },
    "return_type": "polymer_entity",
    "request_options": {
        "results_content_type": ["experimental"],
        "return_all_hits": True,
        "paginate": {"start": 0, "rows": 1000},
        "results_verbosity": "verbose",
    },
}
r = requests.post(URL, json=query, timeout=90)
print("HTTP", r.status_code)
data = r.json()
print("total_count:", data.get("total_count"))
res = data.get("result_set", [])
print("hits returned:", len(res))

out = {}
for hit in res:
    pdb = hit["services"]["entity"]["entity_container_identifiers"]["entry_id"].upper()
    ident = hit["services"]["entity"]["rcsb_polymer_entity_container_identifiers"]
    chains = ident.get("auth_asym_ids") or []
    poly = hit["services"]["entity"].get("entity_poly", {})
    seq = poly.get("pdbx_seq_one_letter_code_can") or ""
    seq = seq.replace("\n", "")
    aligns = hit["services"]["entity"].get("rcsb_polymer_entity_align") or []
    uniprot_align = []
    for a in aligns:
        if a.get("reference_database_name") == "UniProt":
            acc = a.get("reference_database_accession")
            regions = a.get("aligned_regions") or []
            for reg in regions:
                uniprot_align.append({
                    "accession": acc,
                    "e_beg": reg.get("entity_beg_seq_id"),
                    "e_end": reg.get("entity_end_seq_id"),
                    "length": reg.get("length"),
                    "ref_beg": reg.get("ref_beg_seq_id"),
                    "ref_end": reg.get("ref_end_seq_id"),
                    "q_identity": reg.get("q_identity"),
                })
    out.setdefault(pdb, {"chains": [], "seq_len": len(seq), "align": []})
    for c in chains:
        if c not in out[pdb]["chains"]:
            out[pdb]["chains"].append(c)
    out[pdb]["align"].extend(uniprot_align)

json.dump(out, open("/workspace/egfr_entities_rcsb.json", "w"))
print("entries with P00533 entities:", len(out))

# sanity check suspicious entries
for pdb in ["1M17", "1M14", "1IVO", "1XKK", "2GS6", "5D41", "6P1D", "4ZAU", "1M17"]:
    if pdb in out:
        d = out[pdb]
        print(f"\n{pdb}: chains={d['chains']} seq_len={d['seq_len']}")
        for a in d["align"]:
            print("   ", a)
