Now I'll build the EGFR–modulator complex list from BindingDB and validate every PDB against SIFTS chain mapping.

<execute>
#!BASH
cat > /workspace/step4_complexes.py <<'PYEOF'
import pandas as pd, json, re, requests, time
from concurrent.futures import ThreadPoolExecutor

df = pd.read_pickle("/workspace/bindingdb_egfr.pkl")
print("BindingDB EGFR rows:", len(df))

def split_pdb(s):
    if not isinstance(s, str): return []
    return [p.strip().upper() for p in re.split(r"[;,]", s) if re.fullmatch(r"\d[A-Za-z0-9]{3}", p.strip())]

df["pdb_list"] = df["PDB ID(s) for Ligand-Target Complex"].apply(split_pdb)
df["het"] = df["Ligand HET ID in PDB"].astype(str).str.strip().str.upper().replace("NAN", "")
df["het"] = df["het"].apply(lambda x: x if re.fullmatch(r"[A-Z0-9]{1,5}", x) else "")

pairs = {}
for _, r in df.iterrows():
    if not r["het"]: continue
    for p in r["pdb_list"]:
        pairs.setdefault((p, r["het"]), set())
        name = str(r["BindingDB Ligand Name"])
        pairs[(p, r["het"])].add(name)
print("unique (PDB, HET) pairs from BindingDB:", len(pairs))

# also add BioLiP EGFR (PDB, ligand) pairs as structure inventory
eg = pd.read_pickle("/workspace/biolip_egfr_verified.pkl")
for _, r in eg.iterrows():
    lig = str(r["Ligand"]).strip().upper()
    if not re.fullmatch(r"[A-Z0-9]{1,5}", lig): continue
    pairs.setdefault((str(r["PDB"]).upper(), lig), set())
print("after adding BioLiP inventory:", len(pairs))

pdbs = sorted({p for p, _ in pairs})
print("distinct PDB entries to validate:", len(pdbs))

SIFTS = "https://www.ebi.ac.uk/pdbe/api/mappings/uniprot/{pdb}"
session = requests.Session()
def check(pdb):
    try:
        r = session.get(SIFTS.format(pdb=pdb.lower()), timeout=30)
        if r.status_code != 200: return pdb, {}
        d = r.json().get(pdb.lower(), {}) or {}
        chains = {}
        for acc, det in (d.get("UniProt") or {}).items():
            for m in (det.get("mappings") or []):
                c = (m.get("chain_id") or "").upper()
                if c:
                    chains.setdefault(c, set()).add(acc)
        return pdb, chains
    except Exception as e:
        return pdb, {"__error__": str(e)}

t0 = time.time()
with ThreadPoolExecutor(max_workers=8) as ex:
    res = list(ex.map(check, pdbs))
chain_map = {p: {c: sorted(a) for c, a in ch.items()} for p, ch in res}
json.dump(chain_map, open("/workspace/pdb_chain_uniprot.json", "w"))
ok = {p: ch for p, ch in chain_map.items() if any("P00533" in a for a in ch.values())}
print(f"validated {len(ok)}/{len(pdbs)} PDB entries as containing a P00533 chain in {time.time()-t0:.0f}s")
json.dump({p: sorted({c for c, a in ch.items() if "P00533" in a}) for p, ch in ok.items()},
          open("/workspace/egfr_chain_map.json", "w"))
multi = {p: sorted({c for c, a in ch.items() if "P00533" in a}) for p, ch in ok.items() if len({c for c, a in ch.items() if "P00533" in a}) > 1}
print("entries with >1 EGFR chain:", len(multi))
print("examples:", dict(list(multi.items())[:8]))
