Clear ranking emerging. Let me add cutoff sensitivity and affinity/clinical-drug evidence, plus UniProt/ASD annotation.

<execute>
#!BASH
cat > /workspace/step8_distances.py <<'PYEOF'
import json, os, time, gzip
import numpy as np, requests
from Bio.PDB.MMCIF2Dict import MMCIF2Dict
from concurrent.futures import ThreadPoolExecutor, as_completed

CACHE = "/workspace/cif_cache"; MISSING = (".", "?"); HYD = {"H", "D"}
ALIGN_CACHE = {}

def parse_entry(pdb):
    path = os.path.join(CACHE, f"{pdb}.cif")
    cif = MMCIF2Dict(path)
    cols = ["label_comp_id", "label_seq_id", "label_entity_id", "auth_asym_id",
            "auth_seq_id", "pdbx_PDB_ins_code", "type_symbol",
            "Cartn_x", "Cartn_y", "Cartn_z"]
    data = {c: [str(v).strip() for v in cif["_atom_site." + c]] for c in cols}
    xyz = np.stack([np.array(data["Cartn_x"], float), np.array(data["Cartn_y"], float),
                    np.array(data["Cartn_z"], float)], axis=1)
    return data, xyz

def entity_alignments(pdb):
    if pdb in ALIGN_CACHE: return ALIGN_CACHE[pdb]
    out = {}
    for eid in range(1, 12):
        try:
            r = requests.get(f"https://data.rcsb.org/rest/v1/core/polymer_entity/{pdb}/{eid}", timeout=30)
            if r.status_code != 200: break
            payload = r.json()
        except Exception:
            break
        for al in payload.get("rcsb_polymer_entity_align") or []:
            if al.get("reference_database_name") != "UniProt" or al.get("reference_database_accession") != "P00533":
                continue
            for reg in al.get("aligned_regions") or []:
                first = int(reg["entity_beg_seq_id"]); length = int(reg["length"])
                off = int(reg["ref_beg_seq_id"]) - first
                out.setdefault(str(eid), []).append(("P00533", first, first + length - 1, off))
    ALIGN_CACHE[pdb] = out
    return out

def distances(pdb, het, max_cut=6.0):
    data, xyz = parse_entry(pdb)
    lig_mask = np.array([(c.upper() == het.upper()) and (s in MISSING)
                         for c, s in zip(data["label_comp_id"], data["label_seq_id"])])
    lig_rows = [i for i, m in enumerate(lig_mask) if m and data["type_symbol"][i] not in HYD]
    if not lig_rows: return None
    L = xyz[lig_rows]
    groups = {}
    for i in range(len(xyz)):
        s = data["label_seq_id"][i]
        if s in MISSING or data["type_symbol"][i] in HYD: continue
        key = (data["auth_asym_id"][i], data["auth_seq_id"][i], data["pdbx_PDB_ins_code"][i])
        groups.setdefault(key, []).append(i)
    align = entity_alignments(pdb)
    out = {}
    for key, idxs in groups.items():
        P = xyz[idxs]
        d = float(np.sqrt(((P[:, None, :] - L[None, :, :]) ** 2).sum(axis=2)).min())
        if d > max_cut: continue
        i = idxs[0]
        try: lseq = int(data["label_seq_id"][i])
        except ValueError: continue
        eid = data["label_entity_id"][i]
        acc, unum = None, None
        for (ac, first, last, off) in align.get(eid, []):
            if first <= lseq <= last:
                acc, unum = ac, lseq + off; break
        out[str(key)] = {"chain": key[0], "pdb_number": key[1],
                         "residue_name": data["label_comp_id"][i],
                         "label_seq_id": lseq, "entity_id": eid,
                         "min_distance": round(d, 3),
                         "uniprot_accession": acc, "uniprot_number": unum}
    return out

if __name__ == "__main__":
    pairs = [tuple(x) for x in json.load(open("/workspace/validated_pairs.json"))]
    results = {}
    t0 = time.time()
    def work(it):
        pdb, het = it
        try: return (pdb, het), distances(pdb, het)
        except Exception as e: return (pdb, het), {"__error__": repr(e)[:150]}
    with ThreadPoolExecutor(max_workers=6) as ex:
        futs = [ex.submit(work, it) for it in pairs]
        for i, f in enumerate(as_completed(futs), 1):
            k, v = f.result(); results[f"{k[0]}|{k[1]}"] = v
            if i % 100 == 0: print(f"  {i}/{len(pairs)} ({time.time()-t0:.0f}s)", flush=True)
    json.dump(results, open("/workspace/distances_egfr.json", "w"))
    print("done in", round(time.time()-t0), "s; pairs:", len(results))
PYEOF
