Strong ranking. Now let me add critical nuances: wild-type vs resistance-mutant structures (T790M/C797S), an allosteric-modulator subset, and affinity-filtered counts.

<execute>
#!BASH
cat > /workspace/step12_nuance.py <<'PYEOF'
import json, re, numpy as np, pandas as pd
from collections import defaultdict
import xml.etree.ElementTree as ET

dist = json.load(open("/workspace/distances_egfr.json"))
bdb = pd.read_pickle("/workspace/bindingdb_egfr.pkl")
comp_names = json.load(open("/workspace/comp_names.json"))

EXCLUDE = set("MG ZN MN CA CL NA K SO4 PO4 GOL EDO PEG ACT MES EPE NO3 CIT FMT DOD IPA BME IMD DMS TLA PGE P6G 1PE BU3 UNX SCN OCL C8E NAG MAN BMA FUC GAL GLC NDG BGC EOH MOH XYO MPD TRS PG4 PE4 NHE BCT CAC MLI MRD ACY AZI F09 HEX SF4".split())
NUC = set("ANP ATP ADP AMP ADX A1R ACP ADN AGS AGP GTP GDP GNP APC AP5 5GP UTP UDP CDP TTP".split())
def is_drug(h): return h not in EXCLUDE and h not in NUC and h != "peptide"

# ---------- (a) per-structure residue identity at key positions ----------
key_pos = {790: "gatekeeper (Thr790/Met790)", 797: "covalent (Cys797/Ser797)", 858: "catalytic (Leu858)"}
print("=== Wild-type vs mutant identity at key EGFR positions (structures contacting that position) ===")
for pos, label in key_pos.items():
    wt, mut, other = defaultdict(set), defaultdict(set), defaultdict(set)
    for key, val in dist.items():
        if not isinstance(val, dict): continue
        pdb, het = key.split("|")
        if not is_drug(het): continue
        for v in val.values():
            if v.get("uniprot_accession") == "P00533" and v.get("uniprot_number") == pos and v["min_distance"] <= 4.0:
                rn = v["residue_name"]
                if rn in ("THR", "CYS", "LEU"): wt[rn].add(pdb)
                elif rn in ("MET", "SER"): mut[rn].add(pdb)
                else: other[rn].add(pdb)
    print(f"\n{label}:")
    for rn, s in wt.items(): print(f"   wild-type {rn}: {len(s)} structures e.g. {sorted(s)[:6]}")
    for rn, s in mut.items(): print(f"   mutant   {rn}: {len(s)} structures e.g. {sorted(s)[:6]}")

# ---------- (b) ASD allosteric modulators -> HET codes ----------
root = ET.parse("/biolab_data/asd/ASD_Release_202306_XF/ASD01020000_1.xml").getroot()
sites = []
for s in root.find("Allosteric_Site_List"):
    d = {c.tag: (c.text or "").strip() for c in s}
    sites.append(d)
print("\n=== ASD curated allosteric sites for EGFR (P00533) ===")
for d in sites:
    print(f"   {d.get('Allosteric_PDB')} | mod={d.get('Modulator_Name','')[:40]:42s} chain={d.get('Modulator_Chain')} res={d.get('Modulator_Residue')} alias={d.get('Modulator_Alias')} feature={d.get('Modulator_Feature')}")

def het_at(pdb, chain, resnum):
    import os
    from Bio.PDB.MMCIF2Dict import MMCIF2Dict
    path = f"/workspace/cif_cache/{pdb}.cif"
    if not os.path.exists(path): return None
    cif = MMCIF2Dict(path)
    ch = [str(v).strip() for v in cif["_atom_site.auth_asym_id"]]
    rs = [str(v).strip() for v in cif["_atom_site.auth_seq_id"]]
    cid = [str(v).strip() for v in cif["_atom_site.label_comp_id"]]
    sq = [str(v).strip() for v in cif["_atom_site.label_seq_id"]]
    for i in range(len(ch)):
        if ch[i] == chain and rs[i] == str(resnum) and sq[i] in (".", "?"):
            return cid[i]
    return None

allo_hets = {}
for d in sites:
    pdb = d.get("Allosteric_PDB"); ch = d.get("Modulator_Chain"); rs = d.get("Modulator_Residue")
    if pdb and ch and rs:
        h = het_at(pdb, ch, rs)
        if h: allo_hets.setdefault(h, set()).add(pdb)
print("\nASD allosteric-modulator HET codes:", {k: sorted(v) for k, v in allo_hets.items()})

# ---------- (c) ranking restricted to ASD allosteric modulators ----------
allo_set = set(allo_hets)
res_amo = defaultdict(set); res_amo_struct = defaultdict(set); rname = {}
for key, val in dist.items():
    if not isinstance(val, dict): continue
    pdb, het = key.split("|")
    if het not in allo_set: continue
    for v in val.values():
        if v.get("uniprot_accession") == "P00533" and v.get("uniprot_number") and v["min_distance"] <= 4.0:
            r = int(v["uniprot_number"]); res_amo[r].add(het); res_amo_struct[r].add(pdb); rname[r] = v["residue_name"]
rows = []
for r in sorted(res_amo, key=lambda x: (-len(res_amo[x]), -len(res_amo_struct[x]))):
    rows.append({"residue": f"{rname[r]}{r}", "n_allosteric_modulators": len(res_amo[r]),
                 "modulators": ",".join(sorted(res_amo[r])), "n_structures": len(res_amo_struct[r])})
allo_tab = pd.DataFrame(rows)
allo_tab.to_csv("/workspace/egfr_allosteric_modulator_ranking.csv", index=False)
print("\n=== EGFR residues contacted by ASD-curated ALLOSTERIC modulators (4.0 A) ===")
print(allo_tab.head(20).to_string(index=False))
PYEOF
cd /workspace && python /workspace/step12_nuance.py 2>&1 | tail -70
